# Since Python is not available, perform the modification directly via SQL in Node.js
# Replicating what modify_pending_order_items does:
# 1. Check order is pending ✓ (verified above)
# 2. Check item exists in order ✓ (verified above)
# 3. Check new variant exists and is available ✓ (verified above)
# 4. Calculate price difference: 53.89 - 52.79 = 1.10
# 5. Add payment record for the difference
# 6. Update the order item to the new variant
# 7. Update order status to "pending (item modified)"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const orderId = '#W4705780';
const oldItemId = '9716794911';
const newItemId = '2364909101';
const paymentMethodId = 'credit_card_5360334';

// Verify order is still pending
const order = db.prepare('SELECT status FROM orders WHERE order_id = ?').get(orderId);
if (order.status !== 'pending') {
  console.log('ERROR: Order is not pending. Status:', order.status);
  process.exit(1);
}

// Get old item details
const oldItem = db.prepare('SELECT * FROM order_items WHERE order_id = ? AND item_id = ?').get(orderId, oldItemId);
if (!oldItem) {
  console.log('ERROR: Old item not found in order');
  process.exit(1);
}

// Get new variant details
const newVariant = db.prepare('SELECT * FROM rt_variants WHERE item_id = ? AND product_id = ?').get(newItemId, oldItem.product_id);
if (!newVariant || !newVariant.available) {
  console.log('ERROR: New variant not found or unavailable');
  process.exit(1);
}

const diffPrice = Math.round((newVariant.price - oldItem.unit_price) * 100) / 100;
console.log('Price difference:', diffPrice);

// Begin transaction
const transaction = db.transaction(() => {
  // 1. Update order status
  db.prepare('UPDATE orders SET status = ? WHERE order_id = ?').run('pending (item modified)', orderId);

  // 2. Update order item to new variant
  db.prepare('UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE order_id = ? AND item_id = ?')
    .run(newItemId, newVariant.price, newVariant.options, orderId, oldItemId);

  // 3. Add payment record for price difference
  const txnType = diffPrice >= 0 ? 'payment' : 'refund';
  db.prepare('INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)')
    .run(orderId, txnType, Math.abs(diffPrice), paymentMethodId);
});

transaction();

// Verify the changes
const updatedOrder = db.prepare('SELECT * FROM orders WHERE order_id = ?').get(orderId);
const updatedItems = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(orderId);
const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(orderId);

console.log('Updated order status:', updatedOrder.status);
console.log('Updated items:', JSON.stringify(updatedItems.map(i => ({item_id: i.item_id, name: i.name, price: i.unit_price, options: i.options})), null, 2));
console.log('Payments:', JSON.stringify(payments.map(p => ({type: p.transaction_type, amount: p.amount, method: p.payment_method_id})), null, 2));
"

